contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call supplyTokenTo and check that: if the call does not revert,
    // then imBalances[to] (observed via balanceOfToken) is non-decreasing and
    // address(c).balance (ETH) does not decrease as a result of the call.
    // We also ensure that when supplyTokenTo succeeds the reported token balance
    // of `to` (in mAssets via balanceOfToken) is >= previous value.

    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "invalid to");
        // record observable before-values
        uint256 beforeBalanceOfToken = c.balanceOfToken(to);
        uint256 cEthBefore = address(c).balance;

        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cEthAfter = address(c).balance;
        uint256 afterBalanceOfToken = c.balanceOfToken(to);

        // General rule: If supplyTokenTo did not revert, then the observable
        // balanceOfToken(to) (mAssets) did not decrease, and the contract's ETH
        // balance did not decrease either.
        assert(reverted || (afterBalanceOfToken >= beforeBalanceOfToken && cEthAfter >= cEthBefore));
    }

    receive() external payable {}
}

