contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: parameters drive ERC20 amounts and a beneficiary
    function run(address beneficiary, uint256 supplyAmount, uint256 redeemRequest) public payable {
        require(beneficiary != address(0));
        // precondition: supplyAmount > 0 to make meaningful state changes
        require(supplyAmount > 0);

        // The test deployer is the invoker of c calls (this contract). We must ensure
        // this contract has enough mAsset to transfer to c. We cannot mint tokens here,
        // but we will only observe behavior through c's public functions. To keep the
        // test general we try the call and record whether it reverted.

        // Record imBalances before
        uint256 imBeforeBeneficiary = c.imBalances(beneficiary);
        uint256 imBeforeThis = c.imBalances(address(this));

        // Record this test contract's mAsset balance around supply/redeem
        address tokenAddr = c.depositToken();
        uint256 balBefore = IERC20(tokenAddr).balanceOf(address(this));

        bool supplyReverted;
        try c.supplyTokenTo(supplyAmount, beneficiary) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // After supply attempt, read balances and imBalances
        uint256 imAfterBeneficiary = c.imBalances(beneficiary);
        uint256 imAfterThis = c.imBalances(address(this));
        uint256 balAfterSupply = IERC20(tokenAddr).balanceOf(address(this));

        // Now attempt redeem from beneficiary (we cannot call as beneficiary, so call redeemToken from this contract)
        // redeemToken affects msg.sender's imBalances; so call it from this contract to compare.
        // First, ensure some reasonable redeemRequest (allow zero to be generic)
        bool redeemReverted;
        uint256 mAssetsActual = 0;
        try c.redeemToken(redeemRequest) returns (uint256 returned) {
            redeemReverted = false;
            mAssetsActual = returned;
        } catch {
            redeemReverted = true;
        }

        uint256 balAfterRedeem = IERC20(tokenAddr).balanceOf(address(this));
        uint256 imFinalThis = c.imBalances(address(this));
        uint256 imFinalBeneficiary = c.imBalances(beneficiary);

        // General rule asserted:
        // If redeemToken call did NOT revert, then the numeric increase in this contract's mAsset balance
        // equals the mAssetsActual returned and imBalances[address(this)] decreased (or stayed >=0) by
        // the creditsBurned observed as difference between imBeforeThis and imFinalThis. Also, if redeem succeeded,
        // then the returned mAssetsActual equals balAfterRedeem - balAfterSupply.
        // We cannot observe creditsBurned directly from return value of redeemToken, but imBalances change
        // must reflect burned credits for this caller. We assert these relations when redeem did not revert.

        assert(
            redeemReverted || (
                // returned value matches actual token balance increase
                mAssetsActual == (balAfterRedeem - balAfterSupply)
                && imFinalThis <= imAfterThis
                // imBalances decreased by at most imAfterThis (non-negative)
                && (imAfterThis - imFinalThis) <= imAfterThis
            )
        );
    }

    receive() external payable {}
 }

