contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: try to redeem and assert the invariant described above.
    // Parameters: requested redeem amount (mAsset units)
    function run(uint256 redeemRequest) public payable {
        // No precondition on redeemRequest; allow zero too.

        // Observe this contract's credits before redeem
        uint256 imBefore = c.imBalances(address(this));

        // Observe token address and this contract's token balance before redeem
        address tokenAddr = c.depositToken();
        uint256 balBefore = IERC20(tokenAddr).balanceOf(address(this));

        // Attempt redeemToken and record whether it reverted and any return
        bool redeemReverted;
        uint256 mAssetsActual = 0;
        try c.redeemToken(redeemRequest) returns (uint256 returned) {
            redeemReverted = false;
            mAssetsActual = returned;
        } catch {
            redeemReverted = true;
        }

        // Observe token balance and imBalances after
        uint256 balAfter = IERC20(tokenAddr).balanceOf(address(this));
        uint256 imAfter = c.imBalances(address(this));

        // Assert the general rule: if redeem did not revert, returned amount equals token balance increase,
        // and imBalances for this contract did not increase (should be <= before)
        assert(
            redeemReverted || (
                mAssetsActual == (balAfter - balBefore)
                && imAfter <= imBefore
            )
        );
    }

    // Minimal IERC20 view used to observe balances (allowed to declare local interface here)
    receive() external payable {}
}

