contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: call redeemToken and assert relationship between returned value,
    // token balance change, and imBalances decrease for this contract as the caller.
    function run(uint256 redeemRequest) public payable {
        // Observe credits before redeem via public getter
        uint256 imBefore = c.imBalances(address(this));

        // Observe token address and this contract's token balance before redeem
        address tokenAddr = c.depositToken();
        uint256 balBefore = IERC20(tokenAddr).balanceOf(address(this));

        // Attempt redeemToken and record revert flag and returned value. Must be a top-level call.
        bool redeemReverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemRequest) returns (uint256 returned) {
            redeemReverted = false;
            mAssetsActual = returned;
        } catch {
            redeemReverted = true;
            mAssetsActual = 0;
        }

        // Observe token balance and imBalances after
        uint256 balAfter = IERC20(tokenAddr).balanceOf(address(this));
        uint256 imAfter = c.imBalances(address(this));

        // General rule asserted: if call did not revert then
        // 1) returned value equals observed token balance increase,
        // 2) imBalances did not increase, i.e., imAfter <= imBefore,
        // 3) if creditsBurned (imBefore - imAfter) > 0 then imAfter < imBefore (trivially same),
        //    and returned value is non-negative (always true for uint) — we keep the rule substantive by
        //    requiring that when non-reverting, either im decreased or redeemRequest was zero.
        // The assert is one boolean over observed values and params.
        assert(
            redeemReverted || (
                mAssetsActual == (balAfter - balBefore)
                && imAfter <= imBefore
                && (imBefore == imAfter || redeemRequest != 0)
            )
        );
    }

    receive() external payable {}
}

