    function run(uint256 requestedMAssetAmount) public payable {
        // Observe pre-state via public view function
        uint256 beforeBalance = c.balanceOfToken(address(this));

        bool didRevert;
        uint256 returnedAmount;

        // Top-level mutating call on c, captured with try/catch
        try c.redeemToken(requestedMAssetAmount) returns (uint256 r) {
            didRevert = false;
            returnedAmount = r;
        } catch {
            didRevert = true;
            returnedAmount = 0;
        }

        // Observe post-state
        uint256 afterBalance = c.balanceOfToken(address(this));

        // Single assert expressing the general rule:
        // If the call reverted, the observed balanceOfToken is unchanged.
        // Otherwise (succeeded), the observed balanceOfToken did not increase,
        // and the returned actual mAsset amount is no greater than the requested amount.
        assert(
            didRevert
                ? (afterBalance == beforeBalance)
                : (afterBalance <= beforeBalance && returnedAmount <= requestedMAssetAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call supplyTokenTo(amount, to). We must first ensure this contract has approved and holds tokens
    // but the checker deploys a fresh c and this contract is the deployer of c. We cannot mint ERC20 tokens here.
    // Instead we test a relationship that only uses public views around exchangeRate and balanceOfToken before/after
    // and the observed imBalances effect via balanceOfToken and supplyTokenTo's inputs. We will treat supplyTokenTo as
    // a state-changing call and observe that balanceOfToken(to) increases by at least creditsIssued*exchangeRate/1e18.

    // To satisfy interface restrictions (we cannot manipulate ERC20 here), we choose parameters but without actually
    // transferring tokens the call may revert. We capture revert and require the invariant: if call succeeds then
    // the increase in balanceOfToken(to) is >= computed credits*exchangeRate/1e18 where credits = savAfterCredits - savBeforeCredits.

    function run(uint256 amount, address to) public payable {
        require(to != address(0));

        // Read pre-call observable values
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balBefore = c.balanceOfToken(to);

        // Attempt the state-changing call and capture revert status
        bool reverted;
        try c.supplyTokenTo(amount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable values
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(to);

        // If the call succeeded, then the increase in balanceOfToken(to) (measured in mAsset units)
        // must be at least the increase implied by any increase in imBalances[to] converted to underlying
        // via the exchange rate observed at the time of observation. Since we can only observe balances via balanceOfToken,
        // we assert that if non-reverted then balAfter >= balBefore (balance in underlying should not decrease for the beneficiary).
        // This is a general property: supplying to an address must not reduce its reported underlying balance.
        assert(reverted || balAfter >= balBefore);
    }

    receive() external payable {}
}
